INSERT INTO woorido.meeting_votes (
  id, meeting_id, status, expires_at, created_at, required_count
) VALUES (
  #{id}, #{meetingId}, #{status}, #{deadline}, #{createdAt}, #{requiredCount}
)

mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM AS RNUM FROM ( SELECT mv.id as VOTE_ID, CASE WHEN m.status = 'VOTE' THEN TO_CHAR(m.location) ELSE 'MEETING_ATTENDANCE' END as TYPE, m.title as TITLE, mv.status as STATUS, m.created_by as CREATED_BY_ID, u.nickname as CREATED_BY_NICKNAME, mv.expires_at as DEADLINE, mv.created_at as CREATED_AT, -- 레코드 테이블에서 직접 카운트 (데이터 일관성 보장) (SELECT COUNT(*) FROM woorido.meeting_vote_records mvr WHERE mvr.meeting_vote_id = mv.id AND mvr.choice = 'AGREE') as AGREE_COUNT, (SELECT COUNT(*) FROM woorido.meeting_vote_records mvr WHERE mvr.meeting_vote_id = mv.id AND mvr.choice = 'DISAGREE') as DISAGREE_COUNT, (SELECT COUNT(*) FROM woorido.meeting_vote_records mvr WHERE mvr.meeting_vote_id = mv.id) as TOTAL_VOTE_COUNT FROM woorido.meeting_votes mv JOIN woorido.meetings m ON mv.meeting_id = m.id LEFT JOIN woorido.users u ON m.created_by = u.id WHERE m.challenge_id = #{challengeId}
AND mv.status = #{status}
AND ( (m.status = 'VOTE' AND TO_CHAR(m.location) = #{type}) OR (m.status != 'VOTE' AND 'MEETING_ATTENDANCE' = #{type}) )
ORDER BY mv.created_at DESC ) A WHERE ROWNUM <= #{offset} + #{size} ) WHERE RNUM > #{offset}

SELECT COUNT(*)
FROM woorido.meeting_votes mv
JOIN woorido.meetings m ON mv.meeting_id = m.id
WHERE m.challenge_id = #{challengeId}

  AND mv.status = #{status}


  AND (
    (m.status = 'VOTE' AND TO_CHAR(m.location) = #{type}) OR
    (m.status != 'VOTE' AND 'MEETING_ATTENDANCE' = #{type})
  )

SELECT COUNT(*)
FROM woorido.meeting_vote_records
WHERE meeting_vote_id = #{voteId} AND user_id = #{userId}

